// An offline, CSS 3D learning nook. Scrolling and direct controls share the same stops.
(()=>{
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=k=>{try{return JSON.parse(window.fixiverseStorage.getItem(k)||'null');}catch{return null;}};
const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches||!!get('fixiverse-access-v1')?.motion;
const mobile=()=>matchMedia('(max-width:800px)').matches;
const stops=[
 {label:'Your nook',title:'Learn by fixing.<br>Grow in confidence.',body:'For children who need extra learning support. Build understanding and confidence by testing examples, finding mistakes, and teaching Pip. A tutor can help whenever needed.',button:'Explore the bookshelf',hint:'Choose a book to peek inside.'},
 {label:'Fractions',title:'One whole.<br>A new way<br>to see it.',body:'Pip thinks more pieces means a bigger piece. Build an example. Spot the surprise. Help Pip find a better rule.',button:'Open the fraction book',book:'fraction',hint:'Pull out the green book to compare and repair.'},
 {label:'Patterns',title:'Find the loop.<br>Help it grow.',body:'The little loop has lost its rhythm. Arrange your tiles, follow the pattern, and help Pip put it right.',button:'Open the pattern book',book:'pattern',hint:'Pull out the coral book to spot the repeating loop.'},
 {label:'Together',title:'A little help.<br>A big<br>breakthrough.',body:'Your tutor can see what you tried, where you paused, and a useful thing to practice next. You don’t have to figure it out alone.',button:'Open tutor notes',book:'tutor',hint:'A place for the grown-ups on your team.'}
];
let step=0,timer=null,config=null,opener=null,scrollPending=false,navigating=false,settleTimer=null;
const announce=text=>{document.querySelector('#announcement').textContent=text;};
function pause(){clearInterval(timer);timer=null;root.classList.remove('touring');const b=root.querySelector('[data-shelf="tour"]');if(b){b.innerHTML='<span aria-hidden="true">▷</span> Scroll through the story';b.setAttribute('aria-pressed','false');}}
function setStep(next){if(!root.classList.contains('shelf-home'))return;step=Math.max(0,Math.min(3,next));const s=stops[step];root.dataset.stop=step;root.querySelector('.nook-title').innerHTML=s.title;root.querySelector('.nook-description').textContent=s.body;root.querySelector('.nook-eyebrow').textContent=`0${step+1} / ${step===0?'YOUR LEARNING NOOK':s.label.toUpperCase()}`;root.querySelector('.nook-primary').textContent=s.button;root.querySelector('.shelf-help').textContent=s.hint;root.querySelectorAll('[data-shelf="step"]').forEach(b=>{if(+b.dataset.step===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});root.querySelectorAll('.mission-book').forEach(b=>b.classList.toggle('spotlight',b.dataset.book===s.book));root.querySelector('.tour-position').textContent=`0${step+1} / 04 · ${s.label}`;root.querySelector('[data-shelf="previous"]').disabled=step===0;root.querySelector('[data-shelf="next"]').disabled=step===3;}
function go(next,fromTour=false){if(!fromTour)pause();clearTimeout(settleTimer);setStep(next);const host=root.querySelector('.nook-scroll');if(!host)return;
if(mobile()){root.querySelector('.nook-intro').scrollIntoView({behavior:reduced()?'instant':'smooth',block:'start'});return;}
const distance=Math.max(0,host.offsetHeight-innerHeight),y=host.getBoundingClientRect().top+scrollY+distance*step/3;
navigating=true;window.scrollTo({top:y,behavior:reduced()?'instant':'smooth'});settleTimer=setTimeout(()=>{navigating=false;},900);}
function show(c){pause();clearTimeout(settleTimer);navigating=false;config=c;step=0;document.title='Fixiverse · The learning nook';root.className='hub shelf-home'+(get('fixiverse-access-v1')?.large?' large':'')+(reduced()?' reduced':'');root.dataset.stop='0';
root.innerHTML=`<main id="main" class="nook-scroll"><div class="learning-nook">
<div class="nook-wall" aria-hidden="true"></div><div class="nook-arch" aria-hidden="true"></div><div class="nook-floor" aria-hidden="true"></div><div class="nook-rug" aria-hidden="true"></div>
<header class="nook-header"><button class="nook-brand" data-hub="home" aria-label="Fixiverse home">fixiverse<span>✳</span></button><nav aria-label="Main navigation"><button data-shelf="step" data-step="0">The bookshelf</button><button data-lab="open" data-mission="fraction">The Rule Lab ✧</button><button data-mentor="open" data-mission="fraction">Teach Pip ✦</button><button data-hub="tutor">For tutors <span aria-hidden="true">↗</span></button></nav><div class="nook-access"><button data-hub="text-size" aria-label="Toggle larger text" aria-pressed="${!!get('fixiverse-access-v1')?.large}">Aa</button><button data-hub="voice" aria-label="Read this page aloud">Read aloud <span aria-hidden="true">◖</span></button></div></header>
<section class="nook-intro"><div class="nook-eyebrow">01 / YOUR LEARNING NOOK</div><h1 class="nook-title" id="screen-title" tabindex="-1">${stops[0].title}</h1><p class="nook-description">${stops[0].body}</p><div class="nook-actions"><button class="btn nook-primary" data-shelf="primary">${stops[0].button}</button><button class="nook-text-button" data-hub="tutor">Tutor workspace <span aria-hidden="true">↗</span></button></div><div class="nook-learner"><span class="learner-spark" aria-hidden="true">✳</span><div><b>${esc(c.alias)}’s bookshelf</b><span>${c.repaired} of 2 machines repaired · ${c.storage?'Saved on this device':'Keep this tab open to keep your place'}</span></div></div><span class="nook-reassurance">No timer. No rush. You belong here.</span></section>
<section class="bookshelf-scene" aria-label="Interactive learning bookshelf"><div class="scene-sticker" aria-hidden="true">small steps,<br><b>big things.</b><span>✧</span></div><div class="classroom-print" aria-hidden="true"><span>there’s more than<br>one way to</span><b>FIGURE<br>IT OUT.</b><i>↗</i></div><div class="shelf-orbit" aria-hidden="true"><i></i><span>✧</span></div>
<div class="painted-bookshelf"><div class="shelf-top"><span>THE CURIOSITY COLLECTION</span><i aria-hidden="true">✳</i></div><div class="shelf-inside">
<div class="shelf-row top-shelf"><div class="filler-books" aria-hidden="true"><i class="filler mint"><span>keep wondering</span></i><i class="filler cream"><span>what if?</span></i><i class="filler lilac"><span>little ideas</span></i></div>
<button class="mission-book fraction-book" data-shelf="book" data-book="fraction" aria-label="Open Fraction Foundry book" aria-haspopup="dialog"><span class="book-pages" aria-hidden="true"></span><span class="book-cover"><span class="cover-series">FIXIVERSE / VOL. 01</span><strong>Fraction<br>Foundry</strong><span class="cover-fraction-art" aria-hidden="true"><i>½</i><span><b></b><b></b></span><span><b></b><b></b><b></b><b></b></span></span><span class="cover-footer">A whole new way to see it. <i aria-hidden="true">↗</i></span></span><span class="book-spine" aria-hidden="true">FRACTION FOUNDRY</span></button>
<div class="shelf-end" aria-hidden="true"><span class="ceramic-star">✦</span><span>your ideas<br>belong here</span></div><span class="shelf-edge-label">01 &nbsp; COMPARE · QUESTION · REPAIR</span></div>
<div class="shelf-row middle-shelf"><div class="little-plant" aria-hidden="true"><i></i><i></i><i></i><b></b></div><button class="mission-book pattern-book" data-shelf="book" data-book="pattern" aria-label="Open Pattern Grove book" aria-haspopup="dialog"><span class="book-pages" aria-hidden="true"></span><span class="book-cover"><span class="cover-series">FIXIVERSE / VOL. 02</span><strong>Pattern<br>Grove</strong><span class="cover-pattern-art" aria-hidden="true"><i>☀</i><i>❧</i><i>☀</i><i>?</i></span><span class="cover-footer">Find your own rhythm. <i aria-hidden="true">↗</i></span></span><span class="book-spine" aria-hidden="true">PATTERN GROVE</span></button><button class="rule-lab-book" data-shelf="book" data-book="lab" aria-label="Open the Rule Lab book" aria-haspopup="dialog"><span>A BOOK OF<br>YOUR OWN IDEAS</span><strong>Rule<br>Lab</strong><i aria-hidden="true">✧</i><small>BUILD · TEST · EXPLAIN ↗</small></button><span class="shelf-edge-label">02 &nbsp; NOTICE · BUILD · GROW</span></div>
<div class="shelf-row bottom-shelf"><button class="tutor-notebook mission-book" data-shelf="book" data-book="tutor" aria-label="Open tutor notebook" aria-haspopup="dialog"><span class="notebook-rings" aria-hidden="true"></span><span class="notebook-title">A LITTLE<br><strong>help along<br>the way.</strong><small>TUTOR NOTES <i aria-hidden="true">↗</i></small></span></button><button class="shelf-pip mentor-shelf-book" data-mentor="open" data-mission="fraction" aria-label="Open Teach Pip"><div class="robot"><div class="robot-screen"><i class="eye"></i><i class="eye"></i></div><div class="robot-mouth"></div></div><span>PIP’S SCHOOL<br><b>Teach Pip ↗</b></span></button><span class="shelf-edge-label">03 &nbsp; LEARNING IS BETTER TOGETHER</span></div>
</div><div class="shelf-legs" aria-hidden="true"><i></i><i></i></div></div><p class="shelf-help">${stops[0].hint}</p></section>
<nav class="nook-stops" aria-label="Bookshelf sections">${stops.map((s,i)=>`<button data-shelf="step" data-step="${i}" ${i===0?'aria-current="step"':''}><span>0${i+1}</span><i aria-hidden="true"></i>${s.label}</button>`).join('')}</nav>
<footer class="nook-footer"><span class="nook-scroll-cue"><i aria-hidden="true">↓</i> Scroll to explore<br><small>or choose any book</small></span><div class="nook-tour"><button data-shelf="previous" aria-label="Previous bookshelf section" disabled>←</button><button data-shelf="tour" aria-pressed="false"><span aria-hidden="true">▷</span> Scroll through the story</button><button data-shelf="next" aria-label="Next bookshelf section">→</button><span class="tour-divider" aria-hidden="true"></span><button data-shelf="skip">Choose a book <span aria-hidden="true">↗</span></button></div><span class="tour-position" role="status" aria-live="polite">01 / 04 · Your nook</span></footer></div></main>${window.fixiverseLanding?.()||''}`;
if(!window.fixiverseTour?.scrolling())window.scrollTo(0,0);root.querySelector('#screen-title').focus({preventScroll:true});queueMicrotask(()=>window.fixiverseTour?.mount());
}
const previewData={lab:{name:'The Rule Lab',volume:'03',color:'blue',intro:'What if you wrote the rule?',description:'Build a clue, challenge competing ideas, and give Pip a little recipe of your own.',steps:['Find an experiment where the rules disagree.','Build your recipe with little instruction blocks.','Check the collection. Keep a rule postcard.']},fraction:{name:'Fraction Foundry',volume:'01',color:'green',intro:'Can a smaller number make a bigger piece?',description:'Pip’s fraction machine has a mixed-up rule. You get to be the person who fixes it.',steps:['Build two fraction bars.','Find an example that surprises Pip.','Repair the rule. Try it on new examples.']},pattern:{name:'Pattern Grove',volume:'02',color:'coral',intro:'What comes after the very last tile?',description:'Help a little loop find its rhythm. Your ideas are the clues that make it grow.',steps:['Build a repeating loop with tiles.','Show Pip where the old rule goes wrong.','Fix the rule. Try some fresh patterns.']},tutor:{name:'Tutor notes',volume:'04',color:'blue',intro:'Every little attempt tells a story.',description:'See each learner’s real attempts across both missions and pick a useful next step together.',steps:['Choose a learner nickname.','See comparisons, repairs, and hints used.','Find what to practice next.']}};
function openBook(id,button){pause();const d=previewData[id];if(!d)return;opener=button;dialog.className=`storybook-dialog ${d.color}${reduced()?' reduced':''}${get('fixiverse-access-v1')?.large?' large':''}`;dialog.setAttribute('aria-labelledby','book-preview-title');dialog.innerHTML=`<button class="book-close" data-shelf="close" aria-label="Put book back on shelf">×</button><div class="open-storybook"><div class="storybook-left"><span class="page-eyebrow">THE CURIOSITY COLLECTION / ${d.volume}</span><div class="page-illustration ${id}" aria-hidden="true">${id==='fraction'?'<span>½</span><i></i><i></i>':id==='pattern'?'<span>☀</span><span>❧</span><span>☀</span><span>?</span>':id==='lab'?'<span>✧</span><span>what if?</span>':'<span>✳</span><span>together.</span>'}</div><h2 id="book-preview-title">${d.name}</h2><p>${d.intro}</p><span class="page-number">01</span></div><div class="storybook-right"><span class="page-eyebrow">${id==='tutor'?'FOR YOUR LEARNING TEAM':'YOUR NEXT LITTLE ADVENTURE'}</span><h3>${id==='tutor'?'A useful place to begin.':'You’re the one with the good ideas.'}</h3><p>${d.description}</p><ol>${d.steps.map(t=>`<li>${t}</li>`).join('')}</ol><p class="book-save-note">${id==='fraction'?esc(config.fractionStatus):id==='pattern'?esc(config.patternStatus):'Learner records stay in this browser.'}</p><button class="btn book-start" data-shelf="launch" data-book="${id}">${id==='tutor'?'Open tutor workspace':'Let’s try it'} <span aria-hidden="true">↗</span></button><span class="page-number">02</span></div></div>`;dialog.showModal();dialog.querySelector('.book-start').focus({preventScroll:true});}
function closeBook(){dialog.close();opener?.focus({preventScroll:true});}
dialog.addEventListener('close',()=>{if(dialog.classList.contains('storybook-dialog'))dialog.className='';});
document.addEventListener('click',e=>{const b=e.target.closest('[data-shelf]');if(!b)return;const a=b.dataset.shelf;if(a==='step')go(+b.dataset.step);if(a==='previous')go(step-1);if(a==='next')go(step+1);if(a==='primary'){if(step===0){go(1);if(mobile())root.querySelector('.bookshelf-scene').scrollIntoView({behavior:reduced()?'instant':'smooth',block:'start'});}else openBook(stops[step].book,b);}if(a==='book')openBook(b.dataset.book,b);if(a==='close')closeBook();if(a==='launch'){pause();dialog.close();if(b.dataset.book==='lab'){window.fixiverseLab.show('fraction');}else if(b.dataset.book==='tutor'){location.hash='tutor';window.fixiverseTutor.show();}else window.fixiverseLaunch(b.dataset.book);}if(a==='skip'){pause();go(0);if(mobile())root.querySelector('.bookshelf-scene').scrollIntoView({behavior:reduced()?'instant':'smooth',block:'start'});root.querySelector('.fraction-book').focus({preventScroll:true});announce('Choose the green Fraction Foundry book or the coral Pattern Grove book.');}if(a==='tour'){pause();window.fixiverseTour.open();}});
window.addEventListener('scroll',()=>{if(window.fixiverseTour?.scrolling()||scrollPending||mobile()||!root.classList.contains('shelf-home'))return;scrollPending=true;requestAnimationFrame(()=>{scrollPending=false;const host=root.querySelector('.nook-scroll');if(!host||host.offsetHeight<=innerHeight)return;const p=Math.max(0,Math.min(1,-host.getBoundingClientRect().top/(host.offsetHeight-innerHeight)));const next=Math.round(p*3);if(!navigating&&next!==step)setStep(next);root.style.setProperty('--shelf-tour-progress',p);});},{passive:true});
// Do not let an unattended tour run after navigating to a mission or tutor view.
document.addEventListener('click',e=>{if(e.target.closest('[data-lab],[data-mentor],[data-observe]'))pause();if(e.target.closest('[data-hub="fraction"],[data-hub="pattern"],[data-hub="tutor"],[data-tutor]'))pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
window.addEventListener('wheel',()=>{navigating=false;if(timer)pause();},{passive:true});
window.addEventListener('touchstart',e=>{if(!e.target.closest('.nook-tour')){navigating=false;if(timer)pause();}},{passive:true});
document.addEventListener('keydown',e=>{if(timer&&['ArrowDown','ArrowUp','PageDown','PageUp','Home','End'].includes(e.key))pause();});
window.fixiverseBookshelf={show,pause};
})();

